INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Start Your Florida LLC: Step-by-Step Filing Workshop', 'Enterprise Development LLC', 'Business Networking', 'Ready to turn your business idea into action? Join Enterprise Development LLC for a beginner-friendly workshop showing you how to navigate', 'Ready to turn your business idea into action? Join Enterprise Development LLC for a beginner-friendly workshop showing you how to navigate the Florida LLC filing process yourself. Through a guided demonstration, learn what information to prepare, where to file, and what steps to consider after forming your business. What you’ll learn: How to check business-name availability What information is needed for your LLC application How to navigate the Sunbiz filing process What a registered agent is What an EIN is and where to apply Basic next steps after formation Includes a filing checklist and time for questions. Bring a notebook and your business idea! Location: 3241 Old Winter Garden Road, Orlando, FL 32805. Space is limited. The suite number will be sent to registered attendees before the workshop. Admission covers workshop instruction. Government filing fees and business registration Mor', '2026-10-20T14:00:00Z', '3241 Old Winter Garden Rd', '3241 Old Winter Garden Road, Orlando, FL 32805', 'Orlando', 'FL', '32805', 28.548236, -81.417854, 'Enterprise Development LLC', 0, false, '$58.79+', 'live', 'eventbrite', 'https://www.eventbrite.com/e/start-your-florida-llc-step-by-step-filing-workshop-tickets-2002665423191', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Leveraging Seller Concessions: Workshop for Real Estate Professionals', 'Anthony Alzate', 'Real Estate Meetings', 'In today''s market, buyers are overwhelmed with rising interest rates and agent compensation changes. This free, hands-on workshop gives', 'In today''s market, buyers are overwhelmed with rising interest rates and agent compensation changes. This free, hands-on workshop gives Realtors, brokers, and managers the tools to keep deals alive, close more transactions, and offer financial solutions that make homeownership possible for more buyers. WHAT YOU''LL LEARN Unlock Payment Relief Solutions: How seller interest rate buydowns can shave hundreds off monthly payments, making homes more affordable for your clients. Master Seller Concessions: Creatively cover buyer agent fees with seller concessions, making your offers more competitive in a tough market. Boost Your Closing Rates: Proven strategies that can rescue deals by reducing buyer upfront costs and monthly payments. Deliver Unmatched Value to Clients: Position yourself as a problem-solving expert who offers financial solutions buyers won''t hear from other agents. FREE FOR Mor', '2026-10-20T14:30:00Z', 'Fidelity National Title - Sand Lake', '7208 Sand Lake Road, #102, Orlando, FL 32819', 'Orlando', 'FL', '32819', 28.449623, -81.478717, 'Anthony Alzate', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/leveraging-seller-concessions-workshop-for-real-estate-professionals-tickets-2002529653099', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
