INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Orlando: We Create Real Estate Investors, learn how', 'Real Estate investors', 'Real Estate Meetings', 'Come learn a proven path to becoming a real estate investor and how to scale. 🚀 Jumpstart Your Journey: Wondering how to get into your', 'Come learn a proven path to becoming a real estate investor and how to scale. 🚀 Jumpstart Your Journey: Wondering how to get into your first deal? Our experts guide you through a proven process to kickstart your real estate journey in just 12-24 weeks. No more waiting – it''s time to take action! 🎯 Increase your Profits: Learn how to make more money on each deal than traditional investors! Increase your ROI up to 5 times your current success! 🌟 5 Reasons to Be in Real Estate: Learn the key advantages of investing in real estate – from long-term wealth creation to passive income. Realize why seasoned investors choose real estate as their primary wealth-building tool. 📈 Invest in Your Life, Not Just Your Retirement: Learn to leverage real estate to enhance your lifestyle now, not just during retirement. Discover how smart investments and using the Tax Code effectively can positively impact ', '2026-10-20T16:00:00Z', 'Zoom Event', 'Zoom, Orlando, FL 32805', 'Orlando', 'FL', '32805', 28.534550, -81.400423, 'Real Estate investors', 0, true, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/orlando-we-create-real-estate-investors-learn-how-tickets-1999818696555', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
