INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Get Smart Business & Personal Credit Guidance That Puts You Back in Control', 'Esteem REI', 'Real Estate Meetings', 'This free workshop is designed to help you understand how credit works, why it matters, and how to start improving it with clarity and', 'This free workshop is designed to help you understand how credit works, why it matters, and how to start improving it with clarity and purpose. Investor Readiness Quiz => realdealnetwork.com/investor-readiness?ref=esteem We’ll walk through the fundamentals of credit, the common mistakes people make, and what actually moves the needle when it comes to building a strong financial profile You’ll also get a live look at our Credit AI Tool and how it’s used to guide you step by step through the process of improving your credit and tracking your progress What We’ll Cover • Why credit matters in real estate and financing • What’s really impacting your score • How to start improving your credit the right way • How to use the Credit AI Tool to guide your next steps • What to focus on (and what to ignore) This is not just information. It’s about understanding what to do next and having the tools M', '2026-10-21T00:00:00Z', 'Orlando', 'Online, Orlando, FL 34774', 'Orlando', 'FL', '34774', 28.538383, -81.378927, 'Esteem REI', 0, true, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/get-smart-business-personal-credit-guidance-that-puts-you-back-in-control-tickets-1993694706536', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('[Virtual] Simple Real Estate Strategies That Work (Fun, Free, & Gets You Paid!)', 'Central Florida Real Estate Agent Accelerator', 'Real Estate Meetings', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks of prep just to get started (or worst of all, they just want to sell you their expensive course or coaching). **We decided to do the exact opposite**—and hundreds of agents now agree. Join us **LIVE (virtual) every Wednesday at 9:00 AM CST** for a zero-fluff, action-packed call where active, top-producing agents openly share exactly what’s working right More info: https://www.meetup.com/central-florida-real-estate-agent-accelerator/events/316796632/', '2026-10-21T10:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.550000, -81.180000, 'Central Florida Real Estate Agent Accelerator', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/central-florida-real-estate-agent-accelerator/events/316796632/', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('RE-AI Advantage Lab: Turn AI Into Your Real Estate Advantage', 'Central Florida Real Estate Agent Accelerator', 'Real Estate Meetings', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created faster. Follow up can be smarter. Content can be generated almost instantly. But most agents are still trying to figure out **how to actually use AI in their day-to-day business.** That is exactly what we will be exploring inside the **RE-AI Advantage Lab.** This weekly training is designed specifically for real estate agents who want to learn how to use AI More info: https://www.meetup.com/central-florida-real-estate-agent-accelerator/events/316797624/', '2026-10-21T11:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.550000, -81.180000, 'Central Florida Real Estate Agent Accelerator', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/central-florida-real-estate-agent-accelerator/events/316797624/', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Networking Riches Live: Free 2-Day Virtual Workshop with Casey Eberhart', 'IMPACT - Orlando Real Estate Investors Group', 'Real Estate Meetings', 'Your network is your net worth... and this free 2-day workshop shows you how to cash in on it. Real estate runs on relationships. Your next', 'Your network is your net worth... and this free 2-day workshop shows you how to cash in on it. Real estate runs on relationships. Your next listing, buyer, deal, or referral partner is already somewhere in your network. The question is whether you know how to find them, stand out, and follow up so those connections turn into business. That''s exactly what Casey Eberhart, "The Ideal Networker," teaches in Networking Riches Live. Casey has spent more than 20 years building relationships for a More info: https://www.meetup.com/impact-orl/events/316953659/', '2026-10-21T11:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.540000, -81.370000, 'IMPACT - Orlando Real Estate Investors Group', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/impact-orl/events/316953659/', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('The Mover Problem: What Happens When Employees Change Jobs, Not Companies', 'Orlando Cybersecurity Meetup', 'Technology Meetings', '* Why internal role changes create hidden access risks. * How privilege creep happens. * How to align access with changing', '* Why internal role changes create hidden access risks. * How privilege creep happens. * How to align access with changing responsibilities. * Ways to automate access changes. * Best practices for managing mover identities. More info: https://www.meetup.com/orlando-cybersecurity-meetup/events/316778524/', '2026-10-21T11:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.540000, -81.370000, 'Orlando Cybersecurity Meetup', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/orlando-cybersecurity-meetup/events/316778524/', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Master Public Speaking with Downtown Orlando Toastmasters – Weekly Meeting', 'Downtown Orlando Toastmasters', 'Business Networking', 'Looking to become a more confident speaker, better leader, or simply more comfortable expressing your ideas? Join Downtown Orlando', 'Looking to become a more confident speaker, better leader, or simply more comfortable expressing your ideas? Join Downtown Orlando Toastmasters , where professionals from all walks of life come together each week to learn, grow, and support one another in a fun, encouraging environment. Our meetings are every Wednesday from 7:30–8:45 AM , and guests are always welcome — no pressure, no cost, just a friendly place to practice your communication skills and see what Toastmasters is all about. What makes our club unique is our diverse community — a true mosaic of talent and experience. From young professionals to seasoned leaders, each member brings a fresh perspective and helps create a space where everyone can succeed. Mentorship and encouragement are at the heart of what we do, ensuring that every speaker — from first-timers to veterans — continues to grow in confidence and skill. Start M', '2026-10-21T11:30:00Z', '601 W Livingston St', '601 West Livingston Street, UnionWest Room 111, Orlando, FL 32801', 'Orlando', 'FL', '32801', 28.547811, -81.387518, 'Downtown Orlando Toastmasters', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/master-public-speaking-with-downtown-orlando-toastmasters-weekly-meeting-tickets-1962492052558', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
