INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Gemini AI: More Than Just Another Chatbot', 'AI Tool of the Week', 'Technology Meetings', '# Gemini AI: More Than Just Another Chatbot Most people know Gemini as Google''s answer to ChatGPT — but there''s much more you can do with', '# Gemini AI: More Than Just Another Chatbot Most people know Gemini as Google''s answer to ChatGPT — but there''s much more you can do with it. This week at AI Tool of the Week, we''ll explore Gemini through practical live demonstrations. We''ll cover: 🔬 Deep Research — research complex topics using AI 🛠️ Canvas — create documents, apps and interactive tools 🔗 Connected Apps — work with Google''s ecosystem 🎨 AI image creation and editing 📄 Analyze PDFs and documents 💼 Practical business use cases ⚡ More info: https://www.meetup.com/ai-tool-of-the-week/events/316884286/', '2026-10-21T12:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.540000, -81.370000, 'AI Tool of the Week', 5, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/ai-tool-of-the-week/events/316884286/', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
