INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('(CS)²AI Online™ Seminar: Cybersecurity Vulnerability Reporting & Remediation', 'Orlando Cyber Security for Control Systems', 'Technology Meetings', 'Last year Billy and his team hacked a connected wheelchair and sent it careening down a flight of stairs. Recently the manufacturer issued', 'Last year Billy and his team hacked a connected wheelchair and sent it careening down a flight of stairs. Recently the manufacturer issued a patch to its customers that addresses the authentication and encryption weaknesses we exploited. The update has received 510(k) clearance from the FDA, and the patch is cleared for installation on devices. Thus, the circle is complete, the bugs are no more, and the issues we found have been mitigated. The time between public notification and patch release More info: https://www.meetup.com/orlando-cyber-security-for-control-systems/events/316909561/', '2026-10-21T13:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.540000, -81.370000, 'Orlando Cyber Security for Control Systems', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/orlando-cyber-security-for-control-systems/events/316909561/', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
