INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Cross-Market Business Networking [ONLINE] | All Professionals Welcome', 'Exceptional Entrepreneurs', 'Business Networking', 'Why go it alone? Who might you meet today that could change your life personally or professionally? What connection could open a new door', 'Why go it alone? Who might you meet today that could change your life personally or professionally? What connection could open a new door for you, your business, or someone you care about? All professionals welcome. Especially valuable for small business owners, creatives, consultants, marketers, service providers, collaborators, and other growth-minded professionals seeking meaningful connections across multiple markets. Exceptional Entrepreneurs (" EE ") is one of the largest business networking organizations in the USA, bringing together professionals from many Meetup communities and metro areas. This event is designed for people who want more than the same local circle: potential clients, collaborators, strategic connections, fresh ideas, and new opportunities. Meeting format: First 30 minutes: check-in, arrivals, and breakout rooms on relevant topics Remaining 60 minutes: More info:', '2026-10-23T18:30:00Z', 'Exceptional Entrepreneurs (Online Event via ZOOM link)', '424 East Central Boulevard, Orlando, FL 32801', 'Orlando', 'FL', '32801', 28.542097, -81.371802, 'Exceptional Entrepreneurs', 0, true, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/cross-market-business-networking-online-all-professionals-welcome-tickets-1861057596369', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Amp Your Life Now Summit 2026', 'Amp Your Life LLC', 'Business Networking', 'Maybe this year hasn’t gone exactly as planned. But the year isn’t over—and neither is your opportunity. The 4th Annual Amp Your Life Now', 'Maybe this year hasn’t gone exactly as planned. But the year isn’t over—and neither is your opportunity. The 4th Annual Amp Your Life Now Summit is designed for professionals, entrepreneurs, business owners and leaders ready to grow personally, professionally and holistically. This isn’t about sitting through another day of speeches and leaving inspired for 48 hours. You’ll walk away with practical strategies, meaningful connections and a game plan to strengthen your mindset, leadership, relationships, wellness, business and network. The goal? Finish 2026 strong and enter 2027 with clarity, connections and momentum. And this year is even bigger: 4 years of the Summit meets Founder Manny Buisson’s 40th Birthday Bash , followed by a special After-Hours celebration. You still have time to change how this year ends. Will you be in the room? More info: https://www.eventbrite.com/e/amp-your-li', '2026-10-24T12:30:00Z', 'Aloft by Marriott Orlando Lake Nona', '7215 Corner Drive, Orlando, FL 32827', 'Orlando', 'FL', '32827', 28.382465, -81.280277, 'Amp Your Life LLC', 0, false, '$132.64+', 'live', 'eventbrite', 'https://www.eventbrite.com/e/amp-your-life-now-summit-2026-tickets-1999452489219', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Safe Tax - Job Fair', 'Safe Tax, LLC', 'Business Networking', 'Join us at Safe Tax: Tampa Hiring Event! Safe Tax is growing, and we’re looking for motivated, professional, and community-focused', 'Join us at Safe Tax: Tampa Hiring Event! Safe Tax is growing, and we’re looking for motivated, professional, and community-focused individuals to join our team for the upcoming tax season. Join us for our Safe Tax Tampa Hiring Event, where you’ll have the opportunity to meet members of the Safe Tax team, learn more about our company and available opportunities, and participate in our interview process. We’re Hiring For Managers & Tax Preparers within Orlando, Tampa & surrounding areas. Whether you have previous tax experience or you’re looking for an opportunity to grow with a high-energy, community-driven company, we want to meet you. What to Expect During the hiring event, candidates may participate in: * Candidate check-in * Introduction to Safe Tax and our company culture * Overview of available positions * Group interviews * Individual interviews for selected candidates * More info:', '2026-10-24T15:00:00Z', 'AC Hotel Orlando Downtown', '333 South Garland Avenue, Orlando, FL 32801', 'Orlando', 'FL', '32801', 28.538814, -81.381032, 'Safe Tax, LLC', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/safe-tax-job-fair-tickets-2002651057222', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Model Homes, Mimosas & Medical Professionals', 'Hillary Alvarez', 'Business Networking', 'Did you know you have extra benefits as a Hometown Heroe? Join us for an informative and fun event designed for anyone interested in', 'Did you know you have extra benefits as a Hometown Heroe? Join us for an informative and fun event designed for anyone interested in purchasing a home and looking for expert guidance to get started! You’ll gain valuable insights on: The home buying process from start to finish Loan approval requirements and tips for success Different loan options available to you Homebuyer assistance programs , including Hometown Heroes and more How to navigate today’s real estate market with confidence A contract-to-close overview New construction vs. existing homes — which is right for you? After the session, enjoy a guided tour of beautiful new construction homes — complete with mimosas and great company! ✨ RSVP today — space is limited! Don’t miss this chance to take the first step toward owning your dream home. More info: https://www.eventbrite.com/e/model-homes-mimosas-medical-professionals-tickets', '2026-10-24T15:00:00Z', 'Laureate Park by Dream Finders Homes', '10186 Pearson Avenue, Orlando, FL 32827', 'Orlando', 'FL', '10186', 28.352884, -81.254923, 'Hillary Alvarez', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/model-homes-mimosas-medical-professionals-tickets-2002582138083', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
