INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Cost Segregation for Real Estate Investments', 'Orlando IRA Investing Meetup', 'Real Estate Meetings', 'Why wait decades to capture depreciation deductions that may be available sooner? Cost segregation for real estate investments can', 'Why wait decades to capture depreciation deductions that may be available sooner? Cost segregation for real estate investments can accelerate eligible depreciation into shorter depreciation lives rather than 27.5 or 39 years. This provides the potential to lower taxes earlier and keeping more capital working today. Join Advanta IRA’s Larissa Greene and Kamila "Lily" Kowalska, tax consultant and National Account Executive with CSSI Services, for a practical look at how cost segregation works and More info: https://www.meetup.com/orlando-ira-investing-meetup/events/316868282/', '2026-10-27T12:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.540000, -81.370000, 'Orlando IRA Investing Meetup', 0, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/orlando-ira-investing-meetup/events/316868282/', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Mastermind Inmobiliario: haz que tu marca sea encontrada en la IA', 'Evolution Network', 'Business Networking', 'Mastermind Inmobiliario: haz que tu marca sea encontrada en la era de la inteligencia artificial Este 27 de octubre, Evolution Network', 'Mastermind Inmobiliario: haz que tu marca sea encontrada en la era de la inteligencia artificial Este 27 de octubre, Evolution Network recibe a nuestra speaker invitada, Rosario Rodríguez, en un encuentro para agentes inmobiliarios que quieren fortalecer su presencia digital y destacar en un mercado que está cambiando. Tener experiencia y clientes satisfechos es valioso, pero ¿qué pasa si alguien le pide a ChatGPT que le recomiende un Realtor y tu nombre no aparece? Rosario nos compartirá cómo utilizar el video de forma estratégica para dar visibilidad a nuestra marca y comunicar nuestra experiencia en una era donde la inteligencia artificial también influye en cómo las personas buscan y encuentran profesionales. Una sesión para comprender por qué tu marca necesita ser entendida por las máquinas para poder ser elegida por los humanos, y cómo crear contenido con ese propósito. More info: ', '2026-10-27T13:00:00Z', 'Dockside Lake Nona', '13623 Sachs Avenue, Orlando, FL 32827', 'Orlando', 'FL', '13623', 28.371328, -81.261181, 'Evolution Network', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/mastermind-inmobiliario-haz-que-tu-marca-sea-encontrada-en-la-ia-tickets-2003158140923', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Women in Leadership in Orlando, FL', 'KOGNIORA GLOBAL', 'Business Networking', 'Course Overview Strong, inclusive leadership is essential for building resilient organizations, driving innovation, and creating workplaces', 'Course Overview Strong, inclusive leadership is essential for building resilient organizations, driving innovation, and creating workplaces where individuals can thrive. Women leaders bring diverse perspectives, collaborative approaches, emotional intelligence, and strategic insight that contribute significantly to organizational success. Despite this, many women continue to encounter barriers such as unconscious bias, limited representation in senior leadership, unequal access to opportunities, and challenges in balancing professional and personal responsibilities. Organizations that invest in developing women leaders not only strengthen their leadership pipeline but also foster greater employee engagement, improved decision-making, enhanced innovation, and long-term business performance. Kogniora Global ''s Women in Leadership program is designed to empower current and aspiring women Mo', '2026-10-27T13:00:00Z', 'For venue details reach us at: info@kogniora.com', 'Orlando, FL, Orlando, FL, FL 32801', 'Orlando, FL', 'FL', '32801', 28.541666, -81.375686, 'KOGNIORA GLOBAL', 0, false, '$625.86+', 'live', 'eventbrite', 'https://www.eventbrite.com/e/women-in-leadership-in-orlando-fl-registration-2002079629065', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('How to do business with the City of Orlando', 'City of Orlando', 'Business Networking', 'The City of Orlando, in partnership with the National Entrepreneur Center, invites entrepreneurs and business owners to attend the "How to', 'The City of Orlando, in partnership with the National Entrepreneur Center, invites entrepreneurs and business owners to attend the "How to do business with the City of Orlando" workshop. During this workshop, attendees will learn valuable information about necessary steps and documentation to opening or expanding a business, becoming a certified Small Business Enterprise, programming and assistance offered by the city, how to participate in contracting opportunities and more. NOTE: November''s session will be held on November 17 as a VIRTUAL meeting to account for holiday schedules. More info: https://www.eventbrite.com/e/how-to-do-business-with-the-city-of-orlando-tickets-1992939906910', '2026-10-27T14:00:00Z', 'National Entrepreneur Center', '3201 East Colonial Drive, #suite a20, Orlando, FL 32803', 'Orlando', 'FL', '32803', 28.556553, -81.340843, 'City of Orlando', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/how-to-do-business-with-the-city-of-orlando-tickets-1992939906910', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
