INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Virtual "Show and Tell" of Projects by the Community', 'Google Developer Group Central Florida', 'Technology Meetings', 'Ready to showcase your creativity and ingenuity? Want to see what fun, cool, and innovative projects community members are working on? Then', 'Ready to showcase your creativity and ingenuity? Want to see what fun, cool, and innovative projects community members are working on? Then get ready for our Monthly Creative Exchange! This is your chance to: Showcase Your Craft: Experimenting with AI or trying to kickstart a new app? This is your stage! Demo your latest creations, share your process, and spark inspiration in others. Projects do not have to be perfect or completely refined to help inspire others. The Creative Exchange: Need a More info: https://www.meetup.com/gdg-central-florida/events/314661192/', '2026-10-27T19:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.540000, -81.370000, 'Google Developer Group Central Florida', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/gdg-central-florida/events/314661192/', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Why Leadership, Not Technology, Creates Competitive Advantage', 'CEO Leadership Forums', 'Technology Meetings', 'Technology is accessible. Leadership is the advantage. AI, automation, and emerging technologies are creating opportunities that were', 'Technology is accessible. Leadership is the advantage. AI, automation, and emerging technologies are creating opportunities that were unimaginable just a few years ago. But as those capabilities become more powerful and more accessible, technology alone is no longer a differentiator. The real advantage is what leaders do with it. How do you align innovation with strategy? How do you decide where to invest, what to pursue, and what to ignore? How do you bring people through change, create a culture where innovation can thrive, and turn new capabilities into meaningful business results? The Innovation Advantage brings together C-suite leaders to explore how leadership, not technology, creates lasting competitive advantage. KEY TOPICS WE''LL EXPLORE LEADERSHIP AS THE ADVANTAGE Turn innovation into sustainable competitive advantage. STRATEGY + INNOVATION Align emerging capabilities with real ', '2026-10-27T20:00:00Z', '1000 Legion Pl 15th floor', '1000 Legion Place, #15th floor, Orlando, FL 32801', 'Orlando', 'FL', '32801', 28.558895, -81.379868, 'CEO Leadership Forums', 0, false, '$25+', 'live', 'eventbrite', 'https://www.eventbrite.com/e/why-leadership-not-technology-creates-competitive-advantage-tickets-1999123471117', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Startup Funding 101: What Every New Business Owner Should Know', 'RC Holmes powered by Wealthy Results LLC', 'Business Networking', 'What You''ll Learn During this workshop, we''ll break down: How startup and early-stage business funding actually works What lenders look for', 'What You''ll Learn During this workshop, we''ll break down: How startup and early-stage business funding actually works What lenders look for when evaluating a new business How your personal credit, business structure, revenue, and documentation can affect your options Different funding solutions available to business owners The differences between SBA loans, business lines of credit, business credit, equipment financing, term loans, and other funding strategies Common mistakes business owners make when applying for funding How to determine whether your business is funding-ready Steps you can take now to better position your business for capital Most importantly, you''ll learn why finding funding isn''t simply about choosing a bank or submitting applications. The right funding starts with the right strategy. Who Should Attend? This workshop is ideal for: Aspiring entrepreneurs preparing to M', '2026-10-27T22:00:00Z', '6820 Marwick Ln', '6820 Marwick Lane, Orlando, FL 32827', 'Orlando', 'FL', '32827', 28.369582, -81.282017, 'RC Holmes powered by Wealthy Results LLC', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/startup-funding-101-what-every-new-business-owner-should-know-tickets-2002245739907', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
