INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Hand It Off: What to Delegate First, with Claude [ONLINE]', 'The AI Launchpad', 'Technology Meetings', 'In this session we''ll sort a typical owner''s week into what only the owner should do and what someone else can own, then use Claude to', 'In this session we''ll sort a typical owner''s week into what only the owner should do and what someone else can own, then use Claude to write the handover so the first task leaves your plate this week. Most owners know they should delegate but never decide what goes first. A clear list and a written handover make it easy to start. **What we''ll cover:** • The three questions that decide what to hand off first • Turning one task into clear written steps with Claude • Handing it to a team member, More info: https://www.meetup.com/the-ai-launchpad/events/316859939/', '2026-10-28T12:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.540000, -81.380000, 'The AI Launchpad', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/the-ai-launchpad/events/316859939/', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Presentation Skills Mastery for Professionals in Orlando, FL', 'KOGNIORA GLOBAL', 'Business Networking', 'Course Overview In today’s fast-paced professional world, your ability to communicate ideas clearly and confidently can set you apart. The', 'Course Overview In today’s fast-paced professional world, your ability to communicate ideas clearly and confidently can set you apart. The Presentation Skills Mastery program by Kogniora Global is designed to help you transform the way you present, whether you''re leading meetings, pitching ideas, or delivering business presentations to stakeholders. Delivered as an immersive, instructor-led experience, this hands-on workshop equips you with practical, real-world techniques to engage, influence, and inspire. From structuring compelling presentations to delivering them with confidence and clarity, you will develop the skills needed to communicate with impact in any professional setting. At Kogniora Global , we focus on results-driven learning led by industry practitioners, ensuring that every concept you learn is immediately applicable. You won’t just learn what to say, you’ll master how M', '2026-10-28T13:00:00Z', 'For venue details reach us at: info@kogniora.com', 'Orlando, FL, Orlando, FL, FL 32801', 'Orlando, FL', 'FL', '32801', 28.541666, -81.375686, 'KOGNIORA GLOBAL', 0, false, '$682.69+', 'live', 'eventbrite', 'https://www.eventbrite.com/e/presentation-skills-mastery-for-professionals-in-orlando-fl-registration-1999736420465', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
