INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Can Real Estate Investing change your LIFE? REI Implementational Overview.', 'We Create Real Estate Investors-Orlando - Tampa Bay', 'Real Estate Meetings', '**IMPORTANT: RESERVATION VERIFICATION REQUIRED** When was the best time to plant a tree? -20 Years Ago! When is the next best time to plant', '**IMPORTANT: RESERVATION VERIFICATION REQUIRED** When was the best time to plant a tree? -20 Years Ago! When is the next best time to plant it? -RIGHT NOW! Are YOU ready to build your LEGACY LIFE by working alongside both **local** & **national** Real Estate Investors? At this Meeting, we will discuss our **E.P.I.C Formula** for building your journey through Real Estate Investing: -How to create Short Term and PASSIVE INCOME -Pay off your debt in 1/3rd the time, with NO ADDITIONAL Income -Pay More info: https://www.meetup.com/wecreatereinvestors-orlando/events/316903565/', '2026-10-28T19:00:00-04:00', 'Online event', 'Online event', 'Orlando', 'FL', '', 28.540000, -81.370000, 'We Create Real Estate Investors-Orlando - Tampa Bay', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/wecreatereinvestors-orlando/events/316903565/', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('BOSS Coffee & Connections Orlando | REWI Real Estate Networking', 'Kristen Fisher', 'Real Estate Meetings', 'REWI Network & Chill — Orlando, FL Join us for REWI’s BOSS Coffee & Connections at the Foxtail Coffee House —a relaxed Orlando real estate', 'REWI Network & Chill — Orlando, FL Join us for REWI’s BOSS Coffee & Connections at the Foxtail Coffee House —a relaxed Orlando real estate networking event designed for real conversations and real connections. This is a great opportunity to connect with Orlando-area real estate investors, professionals, entrepreneurs, and REWI members in a casual, no-pressure setting. Whether you’re new to real estate or seasoned, come and build relationships, exchange insights, and expand your local network. No agenda. No presentations. Just meaningful conversation. Sometimes the best opportunities come from simply talking it out. Enjoy networking, food, and drinks while connecting with people who are actively investing and growing in real estate. 👉 Meet REWI''s Rafael Norat and up-and-coming leaders in REWI. I will follow up after the event. More info: https://www.eventbrite.com/e/boss-coffee-connection', '2026-10-28T22:00:00Z', 'HANGAR ORLANDO', '7813 South Orange Avenue, Suite 132, Orlando, FL 32809', 'Orlando', 'FL', '32809', 28.454398, -81.364096, 'Kristen Fisher', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/boss-coffee-connections-orlando-rewi-real-estate-networking-tickets-2003224463295', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
