INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('The Probate Network Lunch & Learn: Supporting Families Through Probate', '@coverbrealtor', 'Real Estate Meetings', 'Grief is hard. Navigating the legal process, making financial decisions, and figuring out what to do with a loved one''s property can make', 'Grief is hard. Navigating the legal process, making financial decisions, and figuring out what to do with a loved one''s property can make an already difficult season even heavier. Families don''t have to go through it alone. The Probate Network brings together professionals who serve families during probate and other life transitions. The goal is to learn, connect, and build relationships so families have access to the people and resources they need. This Lunch & Learn will cover the probate process and updates to summary administration, selling property during and after probate, and financial strategies to help families plan ahead. Professionals in legal services, healthcare, funeral services, real estate, and financial services are invited, along with community members who want to better understand the process. Come share a meal, gain practical knowledge, and make connects that can More', '2026-10-29T15:00:00Z', 'RusTeak', '101 S eola Drive Unit 103, Orlando, FL 32801', 'Orlando', 'FL', '32801', 28.540963, -81.369630, '@coverbrealtor', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/the-probate-network-lunch-learn-supporting-families-through-probate-tickets-2002963025327', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('SQL Fall Workshop', 'Project Codex', 'Technology Meetings', 'Whether you’re building your first app, navigating your first job, or just trying to make sense of all the data around you — learning SQL', 'Whether you’re building your first app, navigating your first job, or just trying to make sense of all the data around you — learning SQL will save you hours and make you way more effective. In this session, we’ll walk through the essentials of SQL in a hands-on, no-pressure format. You’ll connect to a real dataset, write actual queries, and start seeing patterns in data that were just noise before. We’ll cover: * Pulling and filtering rows (SELECT, WHERE) * Sorting and slicing data (ORDER BY, More info: https://www.meetup.com/project-codex/events/316835529/', '2026-10-29T19:00:00-04:00', 'UCF Communication and Media Building', '500 W Livingston St, Orlando, FL 32801, USA', 'Orlando', 'FL', '32801', 28.546723, -81.386108, 'Project Codex', 9, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/project-codex/events/316835529/', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
