INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Business Strategy Lunch :: Meet Me at The Monroe', 'Elevate with Stefan', 'Business Networking', 'Bring your challenges and get answers from years of experience with zero excuses. This isn''t another handshake-and-business-card parade.', 'Bring your challenges and get answers from years of experience with zero excuses. This isn''t another handshake-and-business-card parade. This is where you bring your real challenges, your audacious goals, and your unfiltered questions... and walk out with clarity, strategy, and focus. How it Goes Down: Direct Consultant Access — Bring your business questions about entrepreneurship, sales, startups, operations, technology, funding, or any other challenge keeping you from your next level. No topic is off-limits. No sugar-coating. Just strategic truth. Commit to What''s Next — Declare your bold moves, surrounded by people who''ll both challenge your excuses and champion your audacity. This is about pushing beyond limits, while having your back every step of the way. Real Collaboration — Connect with others who operate at your level. Form partnerships that matter. Share insights that move the ', '2026-10-30T16:30:00Z', 'The Monroe', '448 North Terry Avenue, Orlando, FL 32801', 'Orlando', 'FL', '32801', 28.549225, -81.387308, 'Elevate with Stefan', 0, false, '$13.32+', 'live', 'eventbrite', 'https://www.eventbrite.com/e/business-strategy-lunch-meet-me-at-the-monroe-registration-2003209503550', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
