INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('The Connection Experience: Business Leaders Edition', 'Curated Connections', 'Business Networking', 'THE CONNECTION EXPERIENCE: BUSINESS LEADERS EDITION Traditional Networking Is Dead. Same events. Same faces. Same outcomes. THAT ENDS HERE.', 'THE CONNECTION EXPERIENCE: BUSINESS LEADERS EDITION Traditional Networking Is Dead. Same events. Same faces. Same outcomes. THAT ENDS HERE. Let’s face it. What most people call networking is really just a social hour. You show up, mingle, exchange business cards, make small talk, and leave hoping something comes from it. But how many meaningful relationships did you actually build? WELCOME TO THE NEW WAY OF NETWORKING. Join Curated Connections for The Connection Experience: Business Leaders Edition, where we’re bringing entrepreneurs, professionals, and business leaders together for an intentional networking experience. Expect engaging interactions, meaningful conversations, and opportunities to connect beyond the usual introductions. Because meeting people is only the beginning. This is where networking gets intentional. EVENT DETAILS 📅 Wednesday, November 4, 2026 🕡 Doors Open: 6:30 PM ', '2026-11-04T23:30:00Z', '820 Main Ln', '820 Main Lane, Orlando, FL 32801', 'Orlando', 'FL', '32801', 28.531890, -81.377847, 'Curated Connections', 0, false, '$41.74+', 'live', 'eventbrite', 'https://www.eventbrite.com/e/the-connection-experience-business-leaders-edition-registration-2003175810774', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
