INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Village Business Connector 11/13/2026', 'Daisy Ramirez', 'Business Networking', 'Join us on November 13th , at 10:00 AM for the next Village Business Connector, a dynamic gathering designed to help local business owners,', 'Join us on November 13th , at 10:00 AM for the next Village Business Connector, a dynamic gathering designed to help local business owners, professionals, entrepreneurs, and community leaders build meaningful relationships, exchange ideas, and discover new opportunities for growth. This isn''t just another networking event. It''s an intentional space where professionals from diverse industries come together to share experiences, explore partnerships, learn from one another, and strengthen the local business community. Created for anyone launching a new venture, growing an established business, expanding your professional network, or looking for fresh ideas and resources, the Village Business Connector provides an environment where connections lead to collaboration and collaboration leads to opportunity. 🌿 What to Expect: 10:00 AM – Check-In & Welcome 10:15 AM – Introductions 10:30 AM – Mor', '2026-11-13T15:00:00Z', 'HearthStone at Nona Lakes', '10298 Savannah Park Drive, Orlando, FL 32832', 'Orlando', 'FL', '10298', 28.418152, -81.241167, 'Daisy Ramirez', 0, false, 'Paid (see event page)', 'live', 'eventbrite', 'https://www.eventbrite.com/e/village-business-connector-11132026-tickets-2003417852728', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
