INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('November 2026 - Evening Meeting - Full Sail University', 'ISC2 Central Florida Chapter', 'Business Networking', 'Adam Healy (Station70) Bio: Adam Healy is a security executive with more than 20 years of experience spanning the U.S. Intelligence', 'Adam Healy (Station70) Bio: Adam Healy is a security executive with more than 20 years of experience spanning the U.S. Intelligence Community, Fortune 100 enterprises, and financial services. He is the founder and CEO of Station70, a U.S.-based security firm specializing in cryptography, disaster recovery, and authorization controls for institutions. Adam previously served as Chief Information Security Officer at BlockFi, where he led global teams responsible for cybersecurity, fraud prevention, and cloud engineering. Prior to BlockFi, he held senior roles at Palantir Technologies, Microsoft, and Intercontinental Exchange''s Bakkt. Across these roles he led large-scale cybersecurity and modernization programs that secured enterprise data environments for both federal agencies and major global companies. His career began with over a decade in national security, including service as a U.S. ', '2026-11-16T23:00:00Z', 'Full Sail University', '175 University Park Dr, Building 3B, Winter Park, FL 32792', 'Winter Park', 'FL', '32792', 28.594436, -81.303958, 'ISC2 Central Florida Chapter', 0, false, '$28.52+', 'live', 'eventbrite', 'https://www.eventbrite.com/e/november-2026-evening-meeting-full-sail-university-tickets-2003346708935', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
