INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Investing in Businesses', 'GRID Orlando', 'Business Networking', 'From Existing Companies to Early-Stage Opportunities Real estate isn''t the only path to building wealth. Some of the greatest investors in', 'From Existing Companies to Early-Stage Opportunities Real estate isn''t the only path to building wealth. Some of the greatest investors in the world diversify by owning businesses—and understanding how to evaluate, acquire, and invest in companies can unlock an entirely new category of opportunities. Join us for an exciting evening as we explore the world of business investing, from purchasing established cash-flowing companies to understanding opportunities in early-stage businesses and entrepreneurship. You''ll learn: How business acquisitions work What makes a business valuable The key financial metrics buyers should evaluate Common mistakes first-time buyers make Financing options for business acquisitions How investing in operating businesses compares to investing in real estate The role early-stage company investing can play in building long-term wealth Our special guest, Chance Mor', '2026-12-01T22:30:00Z', '11 S Bumby Ave', '11 South Bumby Avenue, Orlando, FL 32803', 'Orlando', 'FL', '32803', 28.506882, -81.352231, 'GRID Orlando', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/investing-in-businesses-tickets-1983063316763', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
