INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Skill & Tell, How Orlando''s Innovators Are Using AI', '🔥 Orlando Innovation League', 'Technology Meetings', 'Curious how AI is actually showing up in the way people build businesses, ship products, and grow their careers? Join Building Our Tech and', 'Curious how AI is actually showing up in the way people build businesses, ship products, and grow their careers? Join Building Our Tech and Startup Weekend Orlando for an evening of "Skill & Tell," where three Orlando tech leaders share the AI skills they''ve built and how those skills are changing the way they work. This isn''t a lecture on AI theory. It''s a hands-on look at real tools, workflows, and strategies from people putting them to work every day. **Orrett Davis**, founder of Mighty More info: https://www.meetup.com/orlando-innovation-league/events/316680304/', '2026-12-09T18:00:00-05:00', 'The Conduit', '1001 N Orange Ave, Orlando, FL 32801, USA', 'Orlando', 'FL', '32801', 28.558046, -81.379184, '🔥 Orlando Innovation League', 3, false, '$5', 'live', 'meetup', 'https://www.meetup.com/orlando-innovation-league/events/316680304/', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Smart Connections Holiday Mixer', 'Level Up Automation, Florida', 'Business Networking', 'What’s the holiday season without a good party? Level Up Automation is excited to host a gathering of community business leaders from', 'What’s the holiday season without a good party? Level Up Automation is excited to host a gathering of community business leaders from across diverse networks, and you’re invited! Join us for an evening of connection, celebration, and giving back. Enjoy great food from local restaurants and special holiday-themed drinks while you meet new people and catch up with familiar faces. Bring your business cards to enter our prize drawings. You might just win something fabulous! And please consider supporting the Samaritan Resource Center Food Drive by bringing sealed, nonperishable food items. Let’s celebrate, connect, and give back, all in one unforgettable evening! More info: https://www.eventbrite.com/e/smart-connections-holiday-mixer-tickets-2002742256000', '2026-12-09T22:30:00Z', 'The Marketplace Building in Avalon Park', '3801 Avalon Park East Blvd, on the "5th Floor", Orlando, FL 32828', 'Orlando', 'FL', '32828', 28.510228, -81.154264, 'Level Up Automation, Florida', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/smart-connections-holiday-mixer-tickets-2002742256000', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
