INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, recurrence, last_verified_at) VALUES ('Economic Development Business Leaders Summit 2027', 'SUMMIT STRATEGIES GROUP LLC', 'Business Networking', 'You are invited to be part of an exclusive gathering of leaders shaping the future of economic development. Join leaders from Puerto Rico', 'You are invited to be part of an exclusive gathering of leaders shaping the future of economic development. Join leaders from Puerto Rico and the United States for a transformative experience. Our mission: The Economic Development Business Leaders Summit is committed to fostering strategic collaboration between business leaders, government officials, entrepreneurs, investors, and community organizations to promote economic growth, innovation, investment opportunities, and sustainable partnerships between Puerto Rico and the United States. Through high-impact networking, educational forums, and business development initiatives, the Summit serves as a platform to connect ideas, create opportunities, and strengthen economic relationships that drive regional and global progress. The Business Leaders Summit Where Leaders Meet Opportunities Business. Investment. Innovation. Connecting More inf', '2027-05-13T12:00:00Z', 'DoubleTree by Hilton Orlando Theme Park Resort', '10100 International Drive, Orlando, FL 32821', 'Orlando', 'FL', '10100', 28.417985, -81.462851, 'SUMMIT STRATEGIES GROUP LLC', 0, false, '$159.75+', 'live', 'eventbrite', 'https://www.eventbrite.com/e/economic-development-business-leaders-summit-2027-tickets-1990871922513', NULL, now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO NOTHING;
